import{_ as e,o as t,c as d,a5 as o}from"./chunks/framework.C1a7WKBV.js";const r="/ai-handbook/assets/tutorials/codex-model-capacity.png",m=JSON.parse('{"title":"Codex 模型繁忙处理","description":"处理 Selected model is at capacity 等容量提示。","frontmatter":{"title":"Codex 模型繁忙处理","description":"处理 Selected model is at capacity 等容量提示。"},"headers":[],"relativePath":"help/codex-errors.md","filePath":"help/codex-errors.md","lastUpdated":1788838685000}'),s={name:"help/codex-errors.md"};function i(l,a,c,n,p,h){return t(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="codex-模型繁忙处理" tabindex="-1">Codex 模型繁忙处理 <a class="header-anchor" href="#codex-模型繁忙处理" aria-label="Permalink to &quot;Codex 模型繁忙处理&quot;">​</a></h1><h2 id="_1-识别容量提示" tabindex="-1">1. 识别容量提示 <a class="header-anchor" href="#_1-识别容量提示" aria-label="Permalink to &quot;1. 识别容量提示&quot;">​</a></h2><p>当看到 <code>Selected model is at capacity. Please try a different model.</code>，表示当前模型的可用容量暂时不足，并不代表本机安装或令牌配置一定有问题。</p><p><img src="'+r+`" alt="Codex 模型容量提示示例"></p><h2 id="_2-处理步骤" tabindex="-1">2. 处理步骤 <a class="header-anchor" href="#_2-处理步骤" aria-label="Permalink to &quot;2. 处理步骤&quot;">​</a></h2><p>先根据提示做判断：</p><table tabindex="0"><thead><tr><th>现象</th><th>优先检查</th></tr></thead><tbody><tr><td><code>Selected model is at capacity</code></td><td>切换模型或渠道，稍后重试</td></tr><tr><td>登录页面打不开或请求超时</td><td>网络环境、代理规则和直连设置</td></tr><tr><td>未授权、令牌无效或权限不足</td><td>令牌是否过期、分组是否正确、当前配置是否已启用</td></tr></tbody></table><p>容量提示和认证、网络错误是不同问题。不要因为容量不足就反复重装客户端或重新生成令牌。</p><h3 id="_2-1-切换模型或渠道" tabindex="-1">2.1 切换模型或渠道 <a class="header-anchor" href="#_2-1-切换模型或渠道" aria-label="Permalink to &quot;2.1 切换模型或渠道&quot;">​</a></h3><p>选择当前可用且延迟较低的模型或渠道后重试，例如可选择控制台监控中状态正常的 <code>gpt-5.6-terra</code>。怎么按任务难度挑选替代模型，见《<a href="/ai-handbook/tips/token-efficiency">效率与省钱技巧</a>》第 1 节。</p><h3 id="_2-2-短暂等待后重试" tabindex="-1">2.2 短暂等待后重试 <a class="header-anchor" href="#_2-2-短暂等待后重试" aria-label="Permalink to &quot;2.2 短暂等待后重试&quot;">​</a></h3><p>等待 1 到 3 分钟，避免立即连续发起大量相同请求。容量通常会随着队列恢复而变化。</p><h3 id="_2-3-降低并发与增加退避" tabindex="-1">2.3 降低并发与增加退避 <a class="header-anchor" href="#_2-3-降低并发与增加退避" aria-label="Permalink to &quot;2.3 降低并发与增加退避&quot;">​</a></h3><p>脚本或批量任务应降低同时发起的请求数，并在失败后使用递增等待时间重试。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 次失败：等待 2 秒</span></span>
<span class="line"><span>第 2 次失败：等待 5 秒</span></span>
<span class="line"><span>第 3 次失败：等待 10 秒</span></span></code></pre></div><p>重试时保留原始错误文本和发生时间，便于在控制台对照用量记录；连续失败超过几分钟，再更换模型或渠道。</p><h2 id="_3-仍无法使用时" tabindex="-1">3. 仍无法使用时 <a class="header-anchor" href="#_3-仍无法使用时" aria-label="Permalink to &quot;3. 仍无法使用时&quot;">​</a></h2><p>检查 STJAPI 控制台中的令牌状态、分组和用量记录。如果网页本身无法打开，先按 <a href="/ai-handbook/getting-started/stjapi#连接异常">STJAPI 账户与网络设置</a> 排查网络连接。</p>`,18)])])}const x=e(s,[["render",i]]);export{m as __pageData,x as default};
